// Filename: watchdog_regs.h
// Author: FPGA Cores 4 U
// Description: C header of the watchdog register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-20
#ifndef WATCHDOG_REGS_H
#define WATCHDOG_REGS_H
#define WATCHDOG_REGS_ID_OFFSET 0x00u
#define WATCHDOG_REGS_VERSION_OFFSET 0x04u
#define WATCHDOG_REGS_DATE_OFFSET 0x08u
#define WATCHDOG_REGS_ID_VALUE 0x57444F47u   /* "WDOG" */
#define WATCHDOG_REGS_CTRL_OFFSET 0x10u   /* CMD */
#define WATCHDOG_REGS_CTRL_RESET 0x00000000u
#define WATCHDOG_REGS_CTRL_EN_SHIFT 0u
#define WATCHDOG_REGS_CTRL_EN_MASK 0x00000001u
#define WATCHDOG_REGS_CTRL_WINDOW_EN_SHIFT 1u
#define WATCHDOG_REGS_CTRL_WINDOW_EN_MASK 0x00000002u
#define WATCHDOG_REGS_CTRL_LOCK_SHIFT 2u
#define WATCHDOG_REGS_CTRL_LOCK_MASK 0x00000004u
#define WATCHDOG_REGS_TIMEOUT_OFFSET 0x14u   /* RW */
#define WATCHDOG_REGS_TIMEOUT_RESET 0x000003E8u
#define WATCHDOG_REGS_PRESCALE_OFFSET 0x18u   /* RW */
#define WATCHDOG_REGS_PRESCALE_RESET 0x00000000u
#define WATCHDOG_REGS_PRETIMEOUT_OFFSET 0x1Cu   /* RW */
#define WATCHDOG_REGS_PRETIMEOUT_RESET 0x00000000u
#define WATCHDOG_REGS_WINDOW_OPEN_OFFSET 0x20u   /* RW */
#define WATCHDOG_REGS_WINDOW_OPEN_RESET 0x00000000u
#define WATCHDOG_REGS_KICK_OFFSET 0x24u   /* WO */
#define WATCHDOG_REGS_KICK_RESET 0x00000000u
#define WATCHDOG_REGS_STATUS_OFFSET 0x28u   /* CMD */
#define WATCHDOG_REGS_STATUS_RESET 0x00000000u
#define WATCHDOG_REGS_STATUS_PRETIMEOUT_SHIFT 0u
#define WATCHDOG_REGS_STATUS_PRETIMEOUT_MASK 0x00000001u
#define WATCHDOG_REGS_STATUS_EXPIRED_SHIFT 1u
#define WATCHDOG_REGS_STATUS_EXPIRED_MASK 0x00000002u
#define WATCHDOG_REGS_STATUS_EARLY_SHIFT 2u
#define WATCHDOG_REGS_STATUS_EARLY_MASK 0x00000004u
#define WATCHDOG_REGS_STATUS_BAD_KEY_SHIFT 3u
#define WATCHDOG_REGS_STATUS_BAD_KEY_MASK 0x00000008u
#define WATCHDOG_REGS_COUNT_OFFSET 0x2Cu   /* RO */
#define WATCHDOG_REGS_COUNT_RESET 0x00000000u
#endif /* WATCHDOG_REGS_H */
